/* Myndirnar eru ný, einföld kennsludæmi. BPMN-línur og atburðatákn eru teiknuð sérstaklega. */
(function(root){
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function text(x,y,value,size=15){const words=String(value).split(' '),lines=[''];for(const word of words){const i=lines.length-1;if((lines[i]+' '+word).trim().length>19&&lines[i])lines.push(word);else lines[i]=(lines[i]+' '+word).trim();}return `<text x="${x}" y="${y-(lines.length-1)*9}" text-anchor="middle" fill="#19373e" stroke="none" font-family="Segoe UI,Arial,sans-serif" font-size="${size}">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?18:0}">${esc(l)}</tspan>`).join('')}</text>`;}
  const defs='<defs><marker id="arrow" markerWidth="9" markerHeight="8" refX="8" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#38565e"/></marker><marker id="open-arrow" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M1 1L9 5L1 9" fill="none" stroke="#38565e" stroke-width="1.5"/></marker></defs>';
  const path=d=>`<path d="${d}" fill="none" stroke="#38565e" stroke-width="1.8" marker-end="url(#arrow)"/>`;
  const task=(x,y,label)=>`<rect x="${x}" y="${y}" width="120" height="58" rx="9" fill="white" stroke="#38565e" stroke-width="1.8"/>${text(x+60,y+34,label)}`;
  const gate=(x,y,symbol)=>`<path d="M${x} ${y-22}l22 22-22 22-22-22Z" fill="white" stroke="#38565e" stroke-width="1.8"/>${symbol==='O'?`<circle cx="${x}" cy="${y}" r="11" fill="none" stroke="#38565e" stroke-width="2"/>`:text(x,y+7,symbol,25)}`;
  function branch(d){return `<svg viewBox="0 0 800 260" role="img" aria-label="${esc('BPMN-líkan: upphaf, '+d.before+', '+d.split+'-klofnun í '+d.top+' eða/og '+d.bottom+', '+d.join+'-sameining, '+d.after+', endir.')}">${defs}<circle cx="25" cy="130" r="15" fill="white" stroke="#38565e" stroke-width="1.8"/>${path('M40 130H65')}${task(65,101,d.before)}${path('M185 130H218')}${gate(240,130,d.split)}${path('M240 108V57H330')}${path('M240 152V203H330')}${task(330,28,d.top)}${task(330,174,d.bottom)}${path('M450 57H540V108')}${path('M450 203H540V152')}${gate(540,130,d.join)}${path('M562 130H596')}${task(596,101,d.after)}${path('M716 130H755')}<circle cx="772" cy="130" r="15" fill="white" stroke="#38565e" stroke-width="4"/>${d.topFlow?text(280,40,d.topFlow,13):''}${d.bottomFlow?text(282,230,d.bottomFlow,13):''}</svg>`;}
  function loop(d){return `<svg viewBox="0 0 700 295" role="img" aria-label="${esc(d.labels.map((v,i)=>v+' hefur '+d.signs[i]+' áhrif á '+d.labels[(i+1)%3]).join('. '))}">${defs}${text(350,36,d.labels[0],17)}${text(545,248,d.labels[1],17)}${text(155,248,d.labels[2],17)}${path('M430 42Q550 65 550 200')}${path('M447 247H250')}${path('M150 205Q150 65 267 42')}${text(570,176,d.signs[0],26)}${text(277,230,d.signs[1],26)}${text(235,70,d.signs[2],26)}</svg>`;}
  function symbol(d){let body='';const cx=200,cy=90;const circle=(radius,extra='')=>`<circle cx="${cx}" cy="${cy}" r="${radius}" fill="white" stroke="#38565e" stroke-width="2" ${extra}/>`;const clock='<circle cx="200" cy="90" r="19" fill="none" stroke="#38565e" stroke-width="1.8"/><path d="M200 76V90L210 98M200 71v4m19 15h-4m-15 19v-4m-19-15h4" fill="none" stroke="#38565e" stroke-width="1.8"/>';switch(d.symbol){
    case 'timer-start':body=circle(32)+clock;break;
    case 'message-catch':case 'message-throw':body=circle(32)+circle(27)+`<rect x="181" y="77" width="38" height="26" fill="${d.symbol==='message-throw'?'#38565e':'white'}" stroke="#38565e" stroke-width="1.7"/><path d="M181 77l19 15 19-15" fill="none" stroke="${d.symbol==='message-throw'?'white':'#38565e'}" stroke-width="1.5"/>`;break;
    case 'boundary-timer':case 'noninterrupting-timer':{const dash=d.symbol==='noninterrupting-timer'?'stroke-dasharray="5 4"':'';body='<rect x="115" y="23" width="170" height="67" rx="10" fill="white" stroke="#38565e" stroke-width="2"/>'+text(200,48,'Vinna beiðni',16)+circle(29,dash)+circle(24,dash)+clock+path('M229 90H340');break;}
    case 'collapsed':case 'call':body=`<rect x="100" y="35" width="200" height="110" rx="11" fill="white" stroke="#38565e" stroke-width="${d.symbol==='call'?5:2}"/>`+text(200,80,d.symbol==='call'?'Sameiginleg athugun':'Afgreiða beiðni',16)+'<rect x="192" y="118" width="16" height="16" fill="white" stroke="#38565e"/><path d="M195 126h10m-5-5v10" stroke="#38565e"/>';break;
    case 'sequence':body=path('M85 90H315');break;
    case 'message-flow':body='<circle cx="85" cy="90" r="5" fill="white" stroke="#38565e" stroke-width="2"/><path d="M90 90H315" stroke="#38565e" stroke-width="2" stroke-dasharray="9 6" marker-end="url(#open-arrow)"/>';break;
    case 'event-gateway':body='<path d="M200 30l60 60-60 60-60-60Z" fill="white" stroke="#38565e" stroke-width="2"/>'+circle(29)+circle(24)+'<path d="M200 71l18 13-7 21h-22l-7-21Z" fill="none" stroke="#38565e" stroke-width="2"/>';break;
    case 'data':body='<path d="M172 40h40l18 18v82h-58Z M212 40v18h18" fill="white" stroke="#38565e" stroke-width="2"/>';break;
    default:body=text(200,90,'Tákn vantar');
  }return `<svg viewBox="0 0 400 180" role="img" aria-label="${esc(d.alt||'BPMN-tákn til túlkunar')}">${defs}${body}</svg>`;}
  root.ExamDiagrams={render(d){if(!d)return'';const type=d.type;const image=type==='branch'?branch(d):type==='loop'?loop(d):symbol(d);return `<figure class="diagram-wrap ${esc(type)}">${image}<figcaption class="diagram-caption">${type==='branch'?'Rektu eitt tilvik frá vinstri til hægri.':type==='loop'?'Örvar sýna orsakatengsl; merki lýsa áhrifum að öðru óbreyttu.':'Túlkaðu táknið út frá lögun, línu og merki.'}</figcaption></figure>`;}};
})(globalThis);
